// Prüft die Eingabe des Orchestrators. Eine leere query stoppt nicht (kein Stop and Error), sondern liefert den festen Wert EINGABE_FEHLT,
// damit der Orchestrator eine Antwort bekommt. fault_test = subaus simuliert den Ausfall des Spezialisten (nur Test, Fehlerfall im Test).
const inp = $input.first().json;
const query = String(inp.query ?? '').trim().slice(0, 4000);
const sessionId = String(inp.session_id ?? '').trim();
const fault = String(inp.fault_test ?? '').trim();
let fehler = '';
if (fault === 'subaus') fehler = 'SPEZIALIST_AUSGEFALLEN';
else if (!query) fehler = 'EINGABE_FEHLT';
return [{ json: { valid: fehler === '', fehler, query, session_id: sessionId, fault_test: fault } }];

// Bündelt die Rückgabe des Agenten für den Orchestrator. werkzeuge trägt jeden Werkzeugaufruf mit Name und Rückgabe,
// damit der Hauptworkflow die Schritte im Adapter auspacken und Werkzeugwahl messen sie wie in v06 bewerten kann.
// v09: Die 4 Werkzeuge liegen am MCP-Server, der Client-Knoten K1_MCP_Auskunft reicht sie an den Agenten. Gemessen (Ausführung 2107): im Protokoll heißt ein Werkzeug
// <Clientname>_<Werkzeugname> mit EINEM Unterstrich (nicht mit zwei, wie zuvor angenommen), und die Rückgabe ist mehrfach verpackt: [{response:[{type:text,text:"[{data:...}]"}]}].
// Der Hauptworkflow vergleicht exakte Namen (K1_Antwortkatalog, Auftragsstand ...) und liest die Rückgabe als Text oder JSON in der Form von v08. Deshalb gibt dieser Knoten
// das Namensende weiter und packt die Rückgabe bis zum eigentlichen Inhalt aus.
// Lange Rückgaben (FAQ-Tabelle, Textstellen, Feiertagsliste) werden gekürzt; der Prüfknoten braucht nur ihren Anfang (Kopfzeile, Quellzeile, Datum).
const KURZ = { K1_Antwortkatalog: 1500, K1_Technikwissen: 1500, Feiertage_nachschlagen: 1500 };
const NAMEN = ['K1_Antwortkatalog', 'K1_Technikwissen', 'Feiertage_nachschlagen', 'Auftragsstand'];
const nameEnde = (t) => { const s = String(t); return NAMEN.find(n => s === n || s.endsWith('_' + n)) || s; };
const auspacken = (v, tiefe = 0) => {
  if (tiefe > 8) return typeof v === 'string' ? v : JSON.stringify(v);
  if (typeof v === 'string') { let p; try { p = JSON.parse(v); } catch (e) { return v; } return (p !== null && typeof p === 'object') ? auspacken(p, tiefe + 1) : v; }
  if (Array.isArray(v)) {
    if (v.length > 0 && v.every(x => x && typeof x === 'object' && x.type === 'text' && typeof x.text === 'string')) return v.map(x => auspacken(x.text, tiefe + 1)).join('\n');
    if (v.length === 1) return auspacken(v[0], tiefe + 1);
    return JSON.stringify(v);
  }
  if (v && typeof v === 'object') {
    if (v.response !== null && typeof v.response === 'object') return auspacken(v.response, tiefe + 1);
    if (typeof v.data === 'string' && v.status === undefined) return auspacken(v.data, tiefe + 1);
    if (typeof v.pageContent === 'string') return v.pageContent;
    return JSON.stringify(v);
  }
  return String(v ?? '');
};
const it = $input.first().json;
const steps = Array.isArray(it.intermediateSteps) ? it.intermediateSteps : [];
const werkzeuge = steps.filter(s => s && s.action && s.action.tool).map(s => {
  const tool = nameEnde(s.action.tool);
  const obs = auspacken(s.observation);
  return { tool, observation: obs.slice(0, KURZ[tool] || 4000) };
});
return [{ json: { status: 'ok', spezialist: 'Auskunfts_Agent', antwort: String(it.output ?? '').trim(), werkzeuge, fehler_text: '' } }];

// Testwerkzeug für den Fehlertest (V5, v11). Liefert nur dann einen Fehler, wenn der Aufrufer fault_test = toolfehler übergeben hat.
// Sonst nur den Leerhinweis KEIN_TEST_AKTIV, damit der Normalbetrieb nichts davon merkt (Werkzeugliste im Ausführungsprotokoll prüfen: 0 Aufrufe).
const fehlertest = String($('Eingabe prüfen [Code]').first().json.fault_test ?? '').trim() === 'toolfehler';
if (fehlertest) throw new Error('TESTFEHLER: Das Testwerkzeug liefert im Fehlertest absichtlich einen Fehler.');
return 'KEIN_TEST_AKTIV: Dieses Werkzeug ist nur für den Fehlertest da und liefert keine Auskunft.';
